<?php
defined('ABSPATH') || exit;
if (!is_user_logged_in()) return;
$search_uid = get_current_user_id();
?>
<h1>AI Search</h1><p><?php echo esc_html($t('Search your knowledge base and receive document excerpts as JSON. Uses the same documents as Advanced Chat without generating a chat answer.', 'Pretražite svoju bazu znanja i dohvatite odlomke dokumenata kao JSON. Koristi iste dokumente kao Advanced Chat, bez generiranja razgovornog odgovora.')); ?></p>
<?php if (!NB_Advanced_Chat::allowed($search_uid)) : ?>
<section class="ws-card"><h2><?php echo esc_html($t('Advanced access required', 'Potreban je Advanced pristup')); ?></h2><p><?php echo esc_html($t('This initial version is available to accounts with active Advanced access. Request a quote to activate your knowledge base.', 'Ova početna verzija dostupna je računima s aktivnim Advanced pristupom. Zatražite ponudu za aktivaciju baze znanja.')); ?></p><a class="button" href="<?php echo esc_url($url('advanced')); ?>"><?php echo esc_html($t('Request access →', 'Zatraži pristup →')); ?></a></section>
<?php return; endif;
$has_search_key = (bool) get_user_meta($search_uid, '_nb_search_key_hash', true);
$once = get_transient('nb_search_key_once_' . $search_uid);
$shown_key = $once ? Neonbreak_Client_Service::decrypt($once) : '';
if ($once) delete_transient('nb_search_key_once_' . $search_uid);
$endpoint = rest_url('neonbreak/v1/search');
$example = "curl -X POST '" . $endpoint . "' \\\n  -H 'Content-Type: application/json' \\\n  -H 'X-Neonbreak-Search-Key: YOUR_SEARCH_KEY' \\\n  --data '{\"query\":\"Business paket\",\"limit\":3}'";
?>
<p class="ws-free"><?php echo esc_html(sprintf($t('%d / %d requests today · 10 per minute', '%d / %d zahtjeva danas · 10 u minuti'), NB_AI_Search::count($search_uid), NB_AI_Search::DAILY_LIMIT)); ?></p>
<div class="ws-access-grid ws-search-grid"><section class="ws-card"><h2><?php echo esc_html($t('Test your search', 'Isprobajte pretragu')); ?></h2><form id="nb-search-form"><label><?php echo esc_html($t('Search query', 'Upit za pretragu')); ?><input name="query" required maxlength="1500" placeholder="<?php echo esc_attr($t('For example: returns policy', 'Primjer: uvjeti povrata')); ?>"></label><button><?php echo esc_html($t('Search knowledge', 'Pretraži znanje')); ?></button><p role="status"></p></form><div id="nb-search-results"></div><details class="ws-search-json"><summary><?php echo esc_html($t('JSON response', 'JSON odgovor')); ?></summary><pre id="nb-search-json"></pre></details></section>
<section class="ws-card"><h2><?php echo esc_html($t('Your JSON API', 'Vaš JSON API')); ?></h2><p><?php echo esc_html($t('Call this endpoint from your server. Never put the Search key into a public widget or frontend code. Your Fireworks and Qdrant keys are not shared.', 'Pozivajte endpoint sa svojeg poslužitelja. Search ključ nemojte stavljati u javni widget ili frontend kod. Fireworks i Qdrant ključevi se ne dijele.')); ?></p><label>Endpoint<input readonly value="<?php echo esc_attr($endpoint); ?>" onclick="this.select()"></label>
<?php if ($shown_key) : ?><div class="ws-search-secret"><strong><?php echo esc_html($t('Copy your new key now — shown once', 'Kopirajte novi ključ sada — prikazuje se samo jednom')); ?></strong><input id="nb-search-new-key" readonly value="<?php echo esc_attr($shown_key); ?>"><button id="nb-search-copy-key" type="button"><?php echo esc_html($t('Copy key', 'Kopiraj ključ')); ?></button><p id="nb-search-copy-status" role="status"></p></div><?php endif; ?>
<p><?php echo esc_html($has_search_key ? $t('A Search key is active. Generating a new key immediately invalidates the old one.', 'Search ključ je aktivan. Generiranje novog ključa odmah poništava stari.') : $t('No active Search key. Create one for server API requests.', 'Nema aktivnog Search ključa. Izradite ga za API pozive s poslužitelja.')); ?></p>
<div class="ws-search-key-actions"><?php foreach (['rotate' => $has_search_key ? $t('Generate a replacement key', 'Generiraj zamjenski ključ') : $t('Create Search key', 'Izradi Search ključ'), 'revoke' => $t('Revoke key', 'Poništi ključ')] as $action => $label) : if ($action === 'revoke' && !$has_search_key) continue; ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="nb_search_key"><input type="hidden" name="key_action" value="<?php echo esc_attr($action); ?>"><input type="hidden" name="return_url" value="<?php echo esc_url($url('search')); ?>"><?php wp_nonce_field('nb_search_key'); ?><button type="submit" data-confirm="<?php echo esc_attr($action === 'revoke' ? $t('Revoke the key? Existing API integrations will stop working.', 'Poništiti ključ? Postojeće API integracije prestat će raditi.') : ($has_search_key ? $t('Replace the key? Existing integrations must use the new key.', 'Zamijeniti ključ? Postojeće integracije moraju koristiti novi ključ.') : '')); ?>"><?php echo esc_html($label); ?></button></form><?php endforeach; ?></div>
<details class="ws-search-json"><summary><?php echo esc_html($t('Example server request', 'Primjer poziva s poslužitelja')); ?></summary><pre><?php echo esc_html($example); ?></pre></details>
<p><?php echo esc_html($t('Limit: 100 requests/day, reset at 00:00 UTC; up to 5 excerpts per request. Tests here count toward the same Search limit. Admitted requests count even if retrieval fails. Fireworks charges query embeddings separately. Similarity score is not a guarantee of correctness.', 'Limit: 100 zahtjeva dnevno, reset u 00:00 UTC; do 5 odlomaka po zahtjevu. Testovi ovdje troše isti Search limit. Prihvaćeni zahtjevi računaju se i ako dohvat ne uspije. Fireworks zasebno naplaćuje embeddings upita. Ocjena sličnosti nije jamstvo točnosti.')); ?></p><a href="<?php echo esc_url($url('knowledge')); ?>"><?php echo esc_html($t('Manage shared knowledge documents →', 'Upravljaj zajedničkim dokumentima baze znanja →')); ?></a></section></div>
<?php
wp_enqueue_script('nb-search', plugins_url('ai-search.js', __FILE__), [], '0.1.0', true);
wp_localize_script('nb-search', 'NBSearch', ['endpoint' => admin_url('admin-ajax.php'), 'nonce' => wp_create_nonce('nb_search_preview'), 'language' => $hr ? 'hr' : 'en']);
?>
